  LanguageConfig_DailyChallengeExpAttenuationRulesTips_CN = {
    Text = "·Cuando el \"Nivel del Guardián\" o el \"Nivel Promedio del Equipo\" es significativamente más alto que el nivel recomendado del desafío, la experiencia de inmersión profunda se reduce."
