  },
  LanguageConfig_LotteryNormalReward_CN = {
    Text = "Objeto normal"
  },
  LanguageConfig_LotteryPhoneticDialogue10_CN = {
    Text = "Sé más devoto, sacrifica un poco más... el reino de dios está observando tus plegarias, algún día te responderá"
  },
  LanguageConfig_LotteryPhoneticDialogue11_CN = {
    Text = "Incluso la persona más común puede ser conmovida por estos versos... ¡Esta flor florece para ti!"
  },
  LanguageConfig_LotteryPhoneticDialogue12_CN = {
    Text = "La poesía tiene sus propias emociones, como las flores tienen su propio lenguaje. Esto es para ti"
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Por favor, míreme, lucharé por siempre"
  },
  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "¿Vienes a presenciar mi triunfo?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "¡Esfuérzate, lucha! ¿Quieres que el maestro te acaricie la cabeza, buen niño?"
  },
  LanguageConfig_LotteryPhoneticDialogue16_CN = {
    Text = "¿Qué puedes salvar con esta mierda?"
  },
  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "¡Vaya, el cliente tiene mucha suerte! ¿Quieres probar otra vez?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "¿Quieres ver más? La tienda tiene mercancías aún más valiosas."
  },
  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "Este informe es muy delicioso, gracias por tu amabilidad."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Gracias por tu amor, querido"
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Bueno, lo acepto. ¿Algo más?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Gracias por tu regalo, por favor acepta estos también."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "He encontrado algunos materiales valiosos, espero que te sean de ayuda."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "Un aperitivo sencillo, que disfrutes tu comida."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "¿Le gusta el plato principal preparado personalmente por el Santo Señor, querido invitado?"
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "No te preocupes demasiado por las técnicas y las reglas."
  },
  LanguageConfig_LotteryPhoneticDialogue26_CN = {
    Text = "La razón solo te enseña a reproducir, la locura te permite crear."
  },
  LanguageConfig_LotteryPhoneticDialogue27_CN = {
    Text = "La gente teme la locura porque nunca han visto la realidad."
  },
  LanguageConfig_LotteryPhoneticDialogue28_CN = {
    Text = "¿Lo viste? ¡El verdadero mundo!"
  },
  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "Vi los colores reales, qué maravillosos."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "Ay, ¡qué buena suerte! Tómalo"
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "La locura y lo absurdo son la verdadera belleza de la realidad, ¡la belleza del arte!"
  },
  LanguageConfig_LotteryPhoneticDialogue31_CN = {
    Text = "Negro, el negro sigue aquí, continúa purificando tus pecados."
  },
  LanguageConfig_LotteryPhoneticDialogue32_CN = {
    Text = "Qué hermoso, vi tu alma pura..."
  },
  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = "Hola, Guardián del Secreto! Incluso si ese incidente volviera a ocurrir, ¿aún me salvarías, verdad? \n... Entonces podré dormir tranquilo. M-muchas gracias, quiero decir, gracias."
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "Últimamente he estado soñando con cosas del pasado, me está volviendo loco; espero que esto sea de alguna utilidad."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "La Madre divina ha hecho un noble sacrificio por el Reino Divino, y estamos dispuestos a intercambiarlo todo por su paz."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "Gracias por tu ofrenda a la Madre divina; espero que esto le traiga una buena noche de sueño."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = "Este sueño se repetirá sin cesar, y tú...\nAgradece, te concederé el permiso para unirte a él."
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "¿Has visto cómo es mi sueño? Esa escena tan sucia y contaminada hasta el extremo..."
  },
  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "Las posesiones ajenas son tan redundantes. Si tienes algún deseo, no dudes en hablarme directamente..."
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "¡Has encontrado un tesoro, joven! ¡Todo en mi tienda son reliquias antiguas!"
  },
  LanguageConfig_LotteryPhoneticDialogue40_CN = {
    Text = "Si te encuentras en las antiguas ruinas del Lejano Oriente, recuerda nunca ofrecer sacrificios imprudentemente—¿demonios y zorros salvajes? Ja... apenas valen la pena mencionarlos."
  },
  LanguageConfig_LotteryPhoneticDialogue41_CN = {
    Text = "¡Bola de carbón, la mejor!"
  },
