    Text = "Derrota en la competencia"
  },
  LanguageConfig_PVPMatchVictory_CN = {
    Text = "Victoria en la competencia"
  },
  LanguageConfig_PVPOpeningVoiceUnlockDesc_CN = {
    Text = "Desbloquea al activar este diálogo en la Fase de Duelo"
  },
  LanguageConfig_PVPRankRewardCountdown_CN = {
    Text = "Temporada restante {s1} días {s2} horas"
  },
  LanguageConfig_PVPRankingRuleDesc_CN = {
    Text = "<Title:[Clasificación de Temporada]>\n[Pregrupo] y [Selección de rueda] tienen sus propias temporadas y clasificaciones de temporada independientes. Las recompensas de la clasificación de temporada se liquidarán al final de cada temporada.\nParticipar en una partida durante la temporada actual te colocará en la clasificación de temporada del modo correspondiente, con tu puntuación más alta de todos los tiempos durante la temporada como base de clasificación. Ganar una partida durante la temporada actual te calificará para recibir recompensas basadas en tu clasificación de temporada al final de la temporada.\n<Title:[Proporción de clasificación]>\nLos títulos de duelo se asignan según los percentiles de puntuación clasificada de la siguiente manera:\n     ·Legendario: 2% superior\n     ·Phase dominator: 2%~10%\n     ·Maestro de ajedrez: 10%~25%\n     ·Élite de fase: 25%~50%\n     ·Aprendiz de ajedrez: 50%~75%\n     ·Novato de fase: después del 75%\nCuando varios Guardianes comparten la misma puntuación, las clasificaciones se determinarán por el orden en que ingresaron a la clasificación; sin embargo, los títulos de duelo y las recompensas se basarán en la clasificación más alta alcanzada con esa puntuación."
