  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "Puedes consumir \"Certificado de Entrenamiento\" para desafiar a los equipos defensivos dispuestos por otros guardianes. Si tienes éxito en el desafío, tu clasificación mejorará. También necesitas organizar cuidadosamente tu equipo defensivo, de lo contrario, podrías ser desafiado con éxito por otros guardianes, lo que causaría una disminución en tu clasificación. Cuanto más alta sea tu clasificación, más \"Insignias de Entrenamiento\" recibirás cada hora. Los \"Certificados de Entrenamiento\" se obtendrán automáticamente con el tiempo. Las \"Insignias de Entrenamiento\" se pueden canjear en la tienda de intercambios por Rosas Doradas, Elixires de Gnosis y otros objetos."
  },
