  LanguageConfig_RailWayStageCrazyMileExpGetDesc_CN = {
    Text = "En esta investigación, puedes obtener un máximo de {s1} \"Puntos VIP\". \nCuerpo de Gnosis de Emergencia usado: {s3}. Actualmente has obtenido: {s2} \"Puntos VIP\".\nFase 1: Derrotar a la élite/Líder otorga \"Puntos VIP\" ×25/75\nFase 2: Derrotar a la élite/Líder otorga \"Puntos VIP\" ×50/150\nFase 3: Derrotar a la élite/Líder otorga \"Puntos VIP\" ×75/225\nLos \"Puntos VIP\" obtenidos en Dificultad/Locura aumentan un 150%/400%.\nCada uso de Cuerpo de Gnosis de Emergencia reduce los \"Puntos VIP\" en un 20%."
  },
  LanguageConfig_RailWayStageCrazyNowDescV2_CN = {
