  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Recompensas de fase>\nPrimera fase: Derrotar a élites/Líderes otorga \"Puntos VIP\" ×25/75 \nSegunda fase: Derrotar a élites/Líderes otorga \"Puntos VIP\" ×50/150 \nTercera fase: Derrotar a élites/Líderes otorga \"Puntos VIP\" ×75/225\n<Title:Reliquias iniciales>\nObtén \"Cámara Prístina de la Pequeña N\" al inicio.\n<OrangeQuality:Armonía Dorada>: \"Armonía Aritmética\" ahora solo aumenta el Coste de Aritmética en 1. Cada 1% de Amplificación de Daño aumenta la Profundidad de la Investigación de la Conciencia en un 1%.\n<RedQuality:Cansancio de larga distancia>: Efecto de Cicatrización –50% durante la batalla."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Reglas especiales>\nCuanto mayor sea la dificultad, más Puntos VIP obtendrás. Si completas las tres fases, los Puntos VIP +150%.\n<Title:Reliquias iniciales>\nObtén \"Cámara Desgastada de la Pequeña N\" al inicio.\n<OrangeQuality:Armonía Dorada>: \"Armonía Aritmética\" ahora solo aumenta el Coste de Aritmética en 1. Cada 1% de Amplificación de Daño aumenta la Profundidad de la Investigación de la Conciencia en un 1%.\n<OrangeQuality:Don Dimensional>: Obtén 1 Reliquia Dimensional aleatoria al inicio. Límite de Mano +1.\n<RedQuality:Cansancio de larga distancia>: Cicatrización –50% durante la batalla.\n<RedQuality:Síntoma de aturdimiento>: Al inicio de la batalla, Aliemus/Keyflare –50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Desafío especial>\nEn dificultad locura, tras completar la tercera fase se desafiará adicionalmente al jefe final de la cuarta fase \"Tawil\".\n<Title:Recompensas de nivel>\nCuanto mayor sea la dificultad del desafío, más \"Puntos VIP\" se obtendrán. Los \"Puntos VIP\" obtenidos al completar las tres fases aumentan un 400%\nAl derrotar al jefe final \"Tawil\", se pueden obtener adicionalmente \"Puntos VIP\" × 1500.\n<Title:Reliquias iniciales>\nAl comenzar la investigación se obtiene la Reliquia \"Cámara Caótica de la Pequeña N\"\n·<OrangeQuality:Armonía Dorada>: El efecto de aumento de Aritmética aportado por la \"Armonía Aritmética\" tiene un máximo de 1 punto. Por cada 1% de Amplificación de Daño que se posea, el efecto de Profundidad de la Investigación de la Conciencia aumenta un 1%.\n·<OrangeQuality:Don Dimensional>: Al comenzar la exploración, se obtiene aleatoriamente 1 Reliquia de Imagen Dimensional y el Tamaño Máximo de la Mano aumenta en 2.\n·<OrangeQuality:Ritual Bendecido>: Las recompensas por derrotar a los jefes de la primera y segunda fase cambian a elegir 1 entre 3 Reliquias bendecidas aleatorias.\n·<RedQuality:Cansancio de larga distancia>: Durante el combate, todos los efectos de cicatrización de PV se reducen un 50%.\n·<RedQuality:Síntoma de aturdimiento>: Al comenzar el combate, la Alienación actual y la Llave Plateada de todos los Cuerpos Despertados se reducen un 50%.\n·<RedQuality:Pasillo de la Noche Eterna>: Al comenzar la exploración, el Aliemus Base y el límite máximo de Llave Plateada de todos los Cuerpos Despertados aumentan un 50%"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Reglas Especiales>\nCuanto mayor sea la dificultad, más Puntos VIP obtendrás. Si completas las tres fases, los Puntos VIP +400%.\n<Title:Reliquias Iniciales>\nObtén la Reliquia \"Cámara Caótica de la Pequeña N\" al inicio.\n<OrangeQuality:Armonía Dorada>: \"Armonía Aritmética\" ahora solo aumenta el Coste de Aritmética en 1. Cada 1% de Amplificación de Daño aumenta la Profundidad de la Investigación de la Conciencia en un 1%.\n<OrangeQuality:Don Dimensional>: Obtén 1 Reliquia Dimensional aleatoria al inicio. Límite de Mano +2.\n<OrangeQuality:Ritual de Bendición>: Los Líderes de la Fase 1 y Fase 2 otorgan 1 de 3 Reliquias Bendecidas a elegir.\n<RedQuality:Cansancio de Larga Distancia>: Cicatrización –50%.\n<RedQuality:Síntoma de Aturdimiento>: Al inicio de la batalla, la Aliemus y Keyflare actuales de todos los Despertados –50%\n<RedQuality:Pasillo de la Noche Eterna>: Alienación básica y límite de Keyflare +50%."
  },
