  },
  LanguageConfig_ResonanceRules_CN = {
    Text = "1. En cada capítulo, los eventos de investigación tienen resonancia, que puede proporcionar una fuerte asistencia durante la investigación. \n2. Al completar un nivel por primera vez, se obtendrán materiales de mejora de resonancia; consumir estos materiales puede activar los efectos de resonancia. \n3. La resonancia aparecerá en los nodos del mapa; moverse a un nodo de resonancia otorgará resonancia en esta exploración."
  },
  LanguageConfig_ResonanceSelectCard_CN = {
