  },
  LanguageConfig_ResonanceUnlock_And_CN = {Text = "Y"},
  LanguageConfig_ResonanceUnlock_Or_CN = {Text = "O"},
  LanguageConfig_ResonanceUpgradeText_CN = {Text = "Mejora"},
  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "En el nodo[regalo bondadoso], se puede agregar una carta de\"respuesta inocente\"al mazo — el consumo de aritmética es 1, otorga 30 puntos de locura al despertador con menor locura, consumo"
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "En el evento de \"Camino de locura\"designa a un Despertado para que sufra una escisión espiritual, perdiendo las 4 cartas de comando iniciales. Después de esto, el camino hacia adelante aparecerá y te permitirá obtener una Creación de oro entre 3 opciones. \n Puedes recuperar las cartas de comando perdidas una por una en los cuatro eventos de \"Fragmento de Consciencia\", las cartas de comando recuperadas tendrán directamente la inscripción única <EnsembleKeywords:\"Ensamble\">."
  },
  LanguageConfig_Resonance_Group_Desc_2_CN = {
    Text = "En el nodo[escultura de cera inacabada], puedes elegir una carta y reducir su consumo de aritmética en 1"
  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "En el nodo[pústula extraña], se puede agregar una carta de\"corazón de anomalía\"al mazo; el consumo de aritmética es 0, después de jugarla, descarta todas las cartas en mano y roba +1 cartas por el número de cartas descartadas, consumo"
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "En el nodo[vino dulce de miel], se puede agregar una carta de\"vino dulce de miel\"al mazo — el consumo de aritmética es 1, obtén 1 capa de barrera temporal, consumo"
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "En el nodo[Ceremonia de la Intercesión] de la etapa \"Délirant de los abismos\" y en etapas posteriores, se puede obtener el efecto \"Extremidad divina\"——al final del turno, causa daño equivalente al 10% de la salud máxima de tu equipo a los enemigos en la fila frontal.\nPuedes añadir una carta \"El veredicto del ejecutor\" a tu mazo——0 de coste de aritmética, al jugarla pierdes el 10% de la salud actual, haciendo que \"Extremidad divina\" cause 3 veces más daño a los enemigos en la fila trasera, si es en una batalla contra un jefe causará 10 veces más daño. Consumo."
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "En “Vela Pura”, puedes agregar una carta “Cortina Utopía” a tu mazo. Consumo de 1 en capacidad, revisa 3 llaves diferentes a las que tienes y elige 1 para liberar de inmediato, esto no activará el enfriamiento de la llave. En la batalla contra el jefe, puedes usar 1 vez adicional. Consumo"
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "Cerca del punto de exploración, se encontrará con un evento de resonancia especial —[Madre nutricia], elija una carta de comando para otorgarle una inscripción especial de[Gestar], pero también le hará obtener 3 cartas de síntomas aleatorias. \n Inscripción de[Gestar]: hace que la carta obtenga Retener, y si está en la mano al final del turno, obtiene una copia original adicional con Retener y Consumo."
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "Cerca del punto de inicio de la exploración, se encontrará con un evento especial de resonancia—[Ceremonia de ingreso], añadiendo [Atardecer polar] a la baraja.\n[Atardecer polar]: Elige 1 tarjeta de comando del mazo de robo o del mazo de descarte para poner en tu mano, haciendo que su coste de aritmética sea 0. (Se consume después de usar 1 vez.)"
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "Cerca del punto de inicio de la exploración, se activará el Evento especial de Resonancia [Ceremonia de ingreso]. Añade [Atardecer polar] a tu baraja, heredando todos los beneficios del capítulo 8."
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "Obtén la reliquia inicial \"Equipo de Investigación\": inicialmente tienes 30 miembros del equipo de investigación. Al comenzar la batalla, coloca 5 cartas de \"Sospecha\" en la biblioteca. \"Sospecha\": al jugarla, elegirás consumir diferentes cantidades de miembros del equipo de investigación para obtener diferentes efectos. \n Durante la exploración, te enfrentarás constantemente a la elección de \"Sospecha\", la pérdida de miembros del equipo de investigación, y al activar el punto de contacto, tendrás la oportunidad de recibir ayuda. Al final de la evacuación, según el número de miembros restantes del equipo de investigación, obtendrás \"Medalla de Rescate\"; cuantos más miembros evacues, más poderosa será la \"Medalla de Rescate\"."
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "Al comenzar la exploración, obtienes la reliquia inicial \"La pluma y la tinta de Horla\": al finalizar la batalla, obtienes 1 capa de \"tinta\", que se consume al alcanzar 2 capas, colocando aleatoriamente 1 carta de \"imagen\" en la baraja. \nPuedes seleccionar \"crear ofrenda\" en el evento de resonancia especial [Regalo de la primavera]: elige 3 cartas de \"imagen\" y deja que Horla cree una \"ofrenda\" para ti."
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "En el evento de resonancia \"La Duda del Productor\", la opción \"Ayuda a un socio\" puede darte un plegaria avanzada 3 eligiendo 1"
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "Exploración comienza con 3 cartas de bonificación en la baraja: <DerivativeCardKeywords_57:\"Una familia cálida\">, <DerivativeCardKeywords_58:\"Amigo sincero\">, <DerivativeCardKeywords_59:\"Una vida pacífica\">. \n\"Una familia cálida\": gana 2 puntos de aritmética. \n\"Amigo sincero\": aplica 1 capa de debilidad y vulnerabilidad a todos los enemigos. \n\"Una vida pacífica\": roba 2 cartas."
  },
  LanguageConfig_Resonance_Group_Desc_Railway_CN = {
    Text = "Por llenar."
  },
  LanguageConfig_Resonance_Group_Desc_SEWD_CN = {
    Text = "\"El evento de\"deseo\"gana una reliquia aleatoria de pecado o una reliquia dorada; el evento de\"confesión\"purifica la reliquia de pecado en una reliquia bendecida; el evento de\"redención\"puede eliminar cartas de síntomas para ganar recompensas.\""
  },
  LanguageConfig_Resonance_Group_Desc_Wangda_CN = {
    Text = "En el evento de resonancia \"Condición del Mandato\", la opción \"Obtener fondos\" te puede dar 25 sigilos negros y una reliquia de plata aleatoria"
  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "En el evento de resonancia \"Conciencia aún no perdida\", baraja una \"Cerebro de repuesto\" en el mazo. \"Cerebro de repuesto\" puede almacenar temporalmente cartas que hayas usado anteriormente y decidir según la situación si las recuperas y las colocas en tu mano."
  },
  LanguageConfig_Resonance_Group_Desc_x2_CN = {
    Text = "En el evento de \"Metamorfosis de la vida\", elige un Despertado para transformarlo en \"Insectoide\".\n La recarga de ira y la regeneración de llave plateada de \"Insectoide\" aumentan un 50%, y el coste de aritmética de todas las tarjetas de comando se reduce en 1, pero se consumen al ser jugadas."
  },
  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "En el evento \"Ritual previo al banquete\", coloca 1 carta \"Mezcla Especial de la Noche de Ofrendas\" en el mazo. \n\"Mezcla Especial de la Noche de Ofrendas\": Coste de Aritmética 1, aumenta temporalmente en un 10% la Probabilidad de Crítico y el Daño Crítico de todos los Despertados. Al jugar \"Mezcla Especial de la Noche de Ofrendas\", coloca 1 tipo de material dentro de ella, ¡para que obtenga permanentemente efectos específicos en esta batalla!"
  },
  LanguageConfig_Resonance_Group_Desc_x4_CN = {
    Text = "En el evento \"Ilusión de Murphy\", coloca 3 \"Reflejos del Ciclo\" en el mazo.\nAl jugar \"Reflejos del Ciclo\", descubre un \"Efecto de Recuerdo\" para desatarlo, consume. Réplica: Todos los despertadores ganan 5 puntos de aliemus."
  },
  LanguageConfig_Resonance_Group_Desc_x5_CN = {
    Text = "Texto temporal, descripción de la función de Resonancia del Capítulo Cinco de las Estrellas."
  },
