  LanguageConfig_ResurrectionCoinPurchaseTips_CN = {
    Text = "(Tras el canje, se consumirá de inmediato y se activará el Renacimiento. Si se retira, se devolverá el Cuerpo de Gnosis de Emergencia. El Cuerpo de Gnosis de Emergencia tiene un límite de compra de 3 veces por semana. Usos restantes actuales: {s1}/3)"
  },
  LanguageConfig_ResurrectionCoinSkillDescription_CN = {
    Text = "Después de la muerte, se puede activar para restaurar toda la vida, locura y energía-llave después de usar un cuerpo de conocimiento de emergencia, e inmunizarse contra todo daño subsiguiente en ese turno"
  },
