  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:Reino sin luz>\n·El Reino sin luz es una serie de niveles de alta dificultad. Completar los niveles permite recibir recompensas sustanciosas. Además, alcanzar una puntuación acumulada en los niveles otorgará recompensas adicionales.\n\n<Title:Requisitos de investigación>\n·Los niveles del Reino sin luz pueden requerir el uso de Despertados de reinos y cantidades específicas para la investigación, los Guardianes pueden consultar en los detalles del nivel y en la interfaz de configuración del equipo.\n\n<Title:Reliquia inicial>\n·Los niveles del Reino sin luz presentan reliquias únicas, que solo son efectivas en el nivel actual; utilizar adecuadamente los efectos de las reliquias hará que la investigación sea mucho más eficiente."
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
    Text = "Selección no cumple con los requisitos del equipo"
  },
  LanguageConfig_School_Activate_CN = {Text = "Activado"},
  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "Al comienzo de cada turno, <CardKeyWord:Fusión Embrionaria> +20 (aumenta con la pérdida de vida, hasta un máximo de 40). Al alcanzar el límite, coloca 1 <CardKeyWord:\"Embrión\"> en tu Mano.\nLa \"Exaltación\" del reino de Carne y sangre consume <CardKeyWord:\"Embrión\"> para activar el efecto <CardKeyWord:Devorar>. Después de la primera Devoración de cada turno, obtén un Escudo del personaje igual al 2% de PV Max y STR temporal igual al 1% de PV Max. (Aumenta con la pérdida de vida, hasta un máximo de 2 veces)"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "Sacrificio Carmesí"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "·Los Despertados del dominio Caos pueden romper las limitaciones del reino y formar equipo con otros Despertados de reino. \n · Si hay un Despertado del Caos en cualquier equipo, se obtiene un 100% de Resistencia a la muerte adicional. \n · Al final del turno y tras liberar \"Exaltar\", <CardKeyWord:Llave Plateada> +50."
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
    Text = "Fenómenos cósmicos"
  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "·La primera copia temporal de la tarjeta de comando jugada en cada turno entra en <CardKeyWord:Espacio Hiperspacial> y activa su efecto de impulso. \n·Cuando el espacio hiperspacial alcanza su límite, obtén un turno ultra adicional, en el que no se roban cartas normalmente, sino que las cartas del espacio hiperspacial se añaden a la mano. En el turno ultra se pueden activar todos los efectos de impulso."
  },
  LanguageConfig_School_Dimension_Title_String_CN = {
    Text = "Salto Dimensional"
  },
  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "·Al comenzar la batalla, se genera 1 tentáculo, que ataca a los enemigos en la primera fila al final del turno.\n·Cada vez que se libera 1 explosión de locura, al final del turno, se impulsa 1 tentáculo para atacar.\n·Por cada 3 puntos de fuerza, se proporciona 1 punto de daño de tentáculo; por cada 3 puntos que disminuya la fuerza, el daño de tentáculo se reduce en 1 punto."
  },
