  },
  LanguageConfig_StorylineGuide_0_CN = {
    Text = "Vivir frente a la muerte."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "Por supuesto, el caos es el final de todo. Pero siempre hay quienes no quieren dejar de luchar, ¿verdad?"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "No mirar directamente al universo sobre la cabeza. No mirar directamente al abismo interior."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Comer es la única virtud en este mundo."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "En el infinito sueño no hay respuestas. Este sueño ha llegado al momento de despertar."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "En el escenario del destino, los papeles que interpretaremos, nunca tuvimos la opción de elegir."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "Oh, viajeros, caminen suavemente hacia esa noche nevada. En la cima de las voluntades vacías, que puedan ser testigos del fin de un gran sueño."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Texto temporal"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Texto temporal"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Texto temporal"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Texto temporal"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Adéntrate en la peligrosa niebla nocturna de Londinium, Guardián del Secreto. Tu camino comienza aquí."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Texto temporal"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Artista, loco, asceta, necio... Esta ciudad es tu galería, las figuras de cera están en el lugar donde comienza la historia, anhelando tu llegada."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "La nieve y el viento de Rai desprecian la matanza, ella te espera, solo para un intercambio. Te traerá el secreto que tanto anhelas. Su precio siempre es cruel, siempre es razonable."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Recuerda, lucha por los recuerdos, muere por los recuerdos. Los recuerdos son nuestro evangelio, nuestra epitafio. Aparte de los recuerdos, no tenemos nada."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Antes de que las estrellas cayeran, oramos hacia el océano: que el suave murmullo de las olas nos proteja en el sueño, que regresemos al abrazo de nuestra patria, sin despertar del largo sueño."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Canta — el antiguo rey ha vuelto a ver su trono. El oráculo sagrado traerá el reino de Dios a cada uno de sus devotos súbditos."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Escucha, ora, llama, reproduce, obedece los ideales más nobles y los deseos más humildes. En nombre de la madre, Él puede perdurar en el caos y el miedo."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "La luz eterna ya ha sido encendida, esa tenue luz iluminará el camino hacia tu destino final."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "Dile a Él, tu respuesta."
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "¡Consigue materiales a través del \"Interludio\" y mejora a tu Despertado!"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "Cómo volverse más fuerte"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "· Desbloquear \"Operación de Investigación\" 1-2: Normal para acceder a \"Ruinas de Disolución\", que otorga una gran cantidad de materiales de desarrollo para Despertadores. \n · Desbloquear \"Operación de Investigación\" 3-10: Normal para acceder a \"Existencia Trascendental\", que proporciona una cantidad sustancial de materiales para mejorar habilidades de Despertadores. \n · Desbloquear \"Nivel de Investigación\" 15 para acceder al \"Segundo Ciclo de Destino\", permitiendo equipar un segundo Ciclo para aumentar el poder de combate. \n · Desbloquear \"Nivel de Investigación\" 25 para acceder al \"Pacto Prohibido\", que proporciona un gran número de Pactos para mejorar las habilidades de los Despertadores."
  },
