  LanguageConfig_TrinketAutoRefineStopByMaxTimeLimit_CN = {
    Text = "100 transcripciones completadas."
  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Transcripción automática>\nLa Transcripción automática puede realizar transcripciones de forma rápida y masiva.\nDurante la Transcripción automática, si un resultado de transcripción contiene 1 atributo desbloqueado con intensidad 8, la Transcripción automática se detendrá.\nLa Transcripción automática puede realizarse hasta 100 veces.\nCuando los materiales sean insuficientes, la transcripción se detendrá automáticamente.\n<Title:Omitir>\nDurante la Transcripción automática, cada resultado de transcripción se mostrará y podrás elegir omitir el proceso de transcripción. Tras omitirlo, el resultado final de la Transcripción automática se mostrará directamente."
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
