  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "No hay ningún Pacto disponible para vincular. Por favor, selecciona al menos uno."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Inmovilización de Pacto>\nLos Gardians del secreto ahora pueden vincular Pactos a los Despertados.\nCada Despertado tiene 6 ranuras de vinculación (un Pacto por ranura).\nUna vez vinculado, el atributo principal del Pacto aumenta un 50%.\nLos Pactos vinculados no aparecerán en tu Inventario ni en el sistema de Alquimia.\nSi un Despertado no tiene ningún Pacto equipado en una ranura de equipo o de Apoyo, su Pacto vinculado se equipará automáticamente.\nMejorar un Pacto vinculado no lo desvinculará; sus atributos potenciados se actualizarán automáticamente.\n\n<Title:Desvinculación de Pacto>\nPara cambiar o eliminar una vinculación, usa la opción de desvincular en la pantalla de Inmovilización de Pacto.\nDesvincular una sola ranura cuesta 10 Pactos del mismo tipo (cualquier posición de ranura puede usarse como coste)."
  },
